const ResponsesAreCompressedAudit = require('../../../audits/byte-efficiency/uses-request-compression.js');
const assert = require('assert');

function generateResponse(filename, type, originalSize, gzipSize) {
  return {
    url: `http://example.com/${filename}`,
    mimeType: `${type}`,
    resourceSize: originalSize,
    gzipSize,
  };
}

const auditResult = ResponsesAreCompressedAudit.audit_({
  ResponseCompression: [
    generateResponse('index.js', 'text/javascript', 100 * 1024, 90 * 1024),
    generateResponse('index.css', 'text/css', 50 * 1024, 37 * 1024),
    generateResponse('index.json', 'application/json', 2048 * 1024, 1024 * 1024),
  ],
});

assert.equal(auditResult.results.length, 2);
